contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint x) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= x);
        uint balBeforeCaller = address(this).balance;
        uint balBeforeC = address(c).balance;
        bool reverted;
        c.withdraw(x); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted ? (address(this).balance == balBeforeCaller && address(c).balance == balBeforeC) : (address(this).balance == balBeforeCaller + x && address(c).balance == balBeforeC - x));
    }
    receive() external payable {}
}

