// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 x) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= x);
        uint balBeforeCaller = address(this).balance;
        uint balBeforeC = address(c).balance;
        bool reverted;
        try c.withdraw(x) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted ? (address(this).balance == balBeforeCaller && address(c).balance == balBeforeC) : (address(this).balance == balBeforeCaller + x && address(c).balance == balBeforeC - x));
    }

    function testFuzz_run(uint256 x) public {
        _run(x);
    }

    receive() external payable {}
}
